"""Independent fictional scan fixtures. No OCR/parser expected values generated by SUT.
Authoring only: Pillow 12.3.0; no product dependency. Raster font not bundled.
"""
import hashlib, json, pathlib, zlib
from PIL import Image, ImageDraw, ImageFont, ImageFilter
ROOT=pathlib.Path(__file__).parent
FONT=pathlib.Path('C:/Windows/Fonts/malgun.ttf')
font=ImageFont.truetype(str(FONT),32)
XS=[50,400,950,1220,1550]; YS=[70,170,450,750]
def scan(kind):
    im=Image.new('RGB',(1600,900),'white'); d=ImageDraw.Draw(im)
    if kind!='borderless':
        for x in XS: d.line((x,YS[0],x,YS[-1]),fill='black',width=3)
        for y in YS: d.line((XS[0],y,XS[-1],y),fill='black',width=3)
    if kind=='broken': d.rectangle((398,230,402,280),fill='white')
    if kind=='merged': d.rectangle((398,73,402,167),fill='white')
    rows=[['업체명','주소','전화번호','혜택'],['가상 가람 식당','가상시 가람로 12','031-123-4567','시험 할인 10%'],['가상 누리 식당','가상시 누리로 23','031-234-5678','시험 할인 20%\n방문 시 적용']]
    if kind=='missing-header':rows[0][0]='항목'
    if kind=='duplicate-header': rows[0][1]='업체명'
    for r,row in enumerate(rows):
        for c,text in enumerate(row):d.multiline_text((XS[c]+15,YS[r]+25),text,font=font,fill='black',spacing=10)
    if kind=='degraded':im=im.resize((400,225)).resize((1600,900)).filter(ImageFilter.GaussianBlur(2))
    return im
def pdf(images,mode='L',partial=False,multi=False,bit=8,bad=False):
    objects=[b'<< /Type /Catalog /Pages 2 0 R >>',b'']
    kids=[]
    for n,image in enumerate(images):
        image=image.convert(mode); channels={'L':1,'RGB':3,'CMYK':4}[mode]
        color={'L':'DeviceGray','RGB':'DeviceRGB','CMYK':'DeviceCMYK'}[mode]
        raw=image.tobytes(); data=zlib.compress(raw,9)
        if bit==1: data=zlib.compress(image.convert('1').tobytes(),9)
        if bad:data=b'not a flate stream'
        image_id=len(objects)+1
        objects.append(f'<< /Type /XObject /Subtype /Image /Width 1600 /Height 900 /BitsPerComponent {bit} /ColorSpace /{color} /Filter /FlateDecode /Length {len(data)} >>\nstream\n'.encode()+data+b'\nendstream')
        extra=''
        if multi:
            other_id=len(objects)+1; data2=zlib.compress(bytes([200])*1600*900,9)
            objects.append(f'<< /Type /XObject /Subtype /Image /Width 1600 /Height 900 /BitsPerComponent 8 /ColorSpace /DeviceGray /Filter /FlateDecode /Length {len(data2)} >>\nstream\n'.encode()+data2+b'\nendstream')
            extra=f'/J {other_id} 0 R'
        placement='400 0 0 225 0 0' if partial else '800 0 0 450 0 0'
        content=f'q {placement} cm /I Do Q\n'.encode()
        if multi: content+=b'q 800 0 0 450 0 0 cm /J Do Q\n'
        content_id=len(objects)+1;objects.append(f'<< /Length {len(content)} >>\nstream\n'.encode()+content+b'endstream')
        page_id=len(objects)+1; kids.append(page_id)
        objects.append(f'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 800 450] /Resources << /XObject << /I {image_id} 0 R {extra} >> >> /Contents {content_id} 0 R >>'.encode())
    objects[1]=f'<< /Type /Pages /Count {len(kids)} /Kids [{' '.join(str(i)+' 0 R' for i in kids)}] >>'.encode()
    result=bytearray(b'%PDF-1.4\n%\xe2\xe3\xcf\xd3\n');offsets=[0]
    for i,obj in enumerate(objects,1): offsets.append(len(result));result+=f'{i} 0 obj\n'.encode()+obj+b'\nendobj\n'
    start=len(result);result+=f'xref\n0 {len(offsets)}\n0000000000 65535 f \n'.encode()
    for off in offsets[1:]:result+=f'{off:010} 00000 n \n'.encode()
    result+=f'trailer\n<< /Size {len(offsets)} /Root 1 0 R >>\nstartxref\n{start}\n%%EOF\n'.encode()
    return bytes(result)
manifest=[]
cases=[('gray','clear','L',{},'ELIGIBLE'),('rgb','clear','RGB',{},'ELIGIBLE'),('multi-image','clear','L',{'multi':True},'UNSUPPORTED'),('partial-image','clear','L',{'partial':True},'UNSUPPORTED'),('one-bit','clear','L',{'bit':1},'UNSUPPORTED'),('cmyk','clear','CMYK',{},'UNSUPPORTED'),('undecodable','clear','L',{'bad':True},'FAILED')]
for kind in ['borderless','broken','merged','missing-header','duplicate-header','degraded']:
    cases.append((kind,kind,'L',{},'ELIGIBLE'))
cases.append(('multipage','clear','L',{},'ELIGIBLE'))
for name,kind,mode,opts,expected in cases:
    im=scan(kind);images=[im,scan('clear')] if name=='multipage' else [im]
    raw=pdf(images,mode,**opts);(ROOT/(name+'.pdf')).write_bytes(raw)
    pixel_hashes=[]
    if expected=='ELIGIBLE':
        for source in images:
            pnm=(b'P5\n' if mode=='L' else b'P6\n')+b'1600 900\n255\n'+source.convert(mode).tobytes()
            pixel_hashes.append(hashlib.sha256(pnm).hexdigest())
    manifest.append(dict(name=name,purpose='fictional technical '+kind,sha256=hashlib.sha256(raw).hexdigest(),imageClass=mode,gridClass=kind,expectedEligibility=expected,license='CC0-1.0',expectedNames=['가상 가람 식당','가상 누리 식당'],expectedRows=2,expectedPixelHashes=pixel_hashes))
scan('clear').save(ROOT/'preview.png')
(ROOT/'manifest.json').write_text(json.dumps(dict(generator='MILIMAP_P43A_FIXTURE_V1',pillowVersion='12.3.0',fontName='Malgun Gothic',fontSha256=hashlib.sha256(FONT.read_bytes()).hexdigest(),fixtures=manifest),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Generated',len(manifest),'independent fixtures')
